SECTION -->\r\n    <section class=\"container course-body-section\" id=\"portfolio-specs-section\" style=\"display:none;\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">PROOF OF WORK</span>\r\n        <h2 class=\"section-title\" id=\"portfolio-specs-title\">Your Production <span class=\"gradient-text\">Portfolio Specs</span></h2>\r\n      </div>\r\n      <div id=\"portfolio-specs-container\" style=\"max-width:860px;\">\r\n        <!-- Populated by JS -->\r\n      </div>\r\n    </section>\r\n\r\n    <!-- PRACTICAL ASSESSMENT FRAMEWORK SECTION -->\r\n    <section class=\"container course-body-section\" id=\"assessment-model-section\" style=\"display:none;\">\r\n      <div class=\"section-header\" style=\"text-align:left; margin-bottom:32px;\">\r\n        <span class=\"section-tag\">EVALUATION MODEL</span>\r\n        <h2 class=\"section-title\" id=\"assessment-model-title\">Practical Assessment & <span class=\"gradient-text\">Competency Model</span></h2>\r\n      </div>\r\n      <div id=\"assessment-model-container\" style=\"max-width:860px;\">\r\n        <!-- Populated by JS -->\r\n      </div>\r\n    </section>\r\n\r\n    <!-- CERTIFICATION SECTION -->\r\n    <section class=\"container course-body-section\" id=\"certification-section\">\r\n      <div class=\"why-visual-card\" style=\"display:grid; grid-template-columns: 1fr 340px; gap:40px; align-items:center;\">\r\n        <div>\r\n          <span class=\"section-tag\">VERIFIED CERTIFICATION</span>\r\n          <h2 style=\"font-size:1.75rem; font-weight:800; color:var(--navy); margin-bottom:12px;\">\r\n            Earn an Industry Recognized <span class=\"gradient-text\">Certificate</span>\r\n          </h2>\r\n          <p id=\"cert-desc\" style=\"color:var(--text-muted); line-height:1.7; margin-bottom:20px;\">\r\n            Upon successful completion of the course and capstone projects, you will receive an ISO-certified credential fr